import { useEffect, useState } from "react";
import { data, Link } from "react-router-dom";

export default function StudentTable() {
    // console.log(useState(1));
    const [students, setStudents] = useState("");
    const DisplayDetails=(id)=>{
        console.log(id);
        
    }

    useEffect(() => {
        fetch('http://localhost:8000/students')
            .then((res) => res.json())
            .then((data) =>
                setStudents(data)).catch((err) =>
                    console.log(err.message))
    }, [])
    return (
        <div className="container">
            <h2>Student Records</h2>
            <div className="table-container">
                {/* <a href="#" className="btn btn-add">Add new Student</a> */}
                <Link to="/student/create" className="btn btn-add">Add new Student</Link>
                <table>
                    <thead>
                        <tr>
                            <th>Id</th>
                            <th>Name</th>
                            <th>Place</th>
                            <th>Phone</th>
                            <th>Acdtions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {
                            students && students.map((item) => (
                                <tr key={item.id}>
                                    <td>{item.id}</td>
                                    <td>{item.name}</td>
                                    <td>{item.place}</td>
                                    <td>{item.phone}</td>
                                    <td>
                                        <button onClick={()=>DisplayDetails(item.id)} className="view-btn">View</button>
                                        <button className="edit-btn">Edit</button>
                                        <button className="delete-btn">Delete</button>
                                    </td>
                                </tr>
                            ))
                        }
                    </tbody>
                </table>
            </div>
        </div>
    )
}
